window.docContents[214].resolve({"/Equiv/#Hoare-Logic--Equiv___-Program-Equivalence--Program-Transformation--The-Constant-Folding-Transformation":{"contents":"An expression is constant if it contains no variable references.Constant folding is an optimization that finds constant\nexpressions and replaces them by their values.\n\ndef Aexp.foldConstants (a : Aexp) : Aexp :=\n  match a with\n  | .num n => .num n\n  | .id x => .id x\n  | aexp { a₁ + a₂ } =>\n    match a₁.foldConstants, a₂.foldConstants with\n    | .num n₁, .num n₂ => .num (n₁ + n₂)\n    | a₁', a₂' => aexp { a₁' + a₂' }\n  | aexp { a₁ - a₂ } =>\n    match a₁.foldConstants, a₂.foldConstants with\n    | .num n₁, .num n₂ => .num (n₁ - n₂)\n    | a₁', a₂' => aexp { a₁' - a₂' }\n  | aexp { a₁ * a₂ } =>\n    match a₁.foldConstants, a₂.foldConstants with\n    | .num n₁, .num n₂ => .num (n₁ * n₂)\n    | a₁', a₂' => aexp { a₁' * a₂' }\n\n@[simp]\ntheorem Aexp.foldConstants_num (n : Nat) :\n    (Aexp.num n).foldConstants = .num n := by rfl\n@[simp]\ntheorem Aexp.foldConstants_id (x : Ident) :\n    (Aexp.id x).foldConstants = .id x := by rfl\n\ntheorem Aexp.foldConstants_cases (a₁ a₂ : Aexp) :\n    (∃ n₁ n₂, a₁.foldConstants = .num n₁ ∧\n      a₂.foldConstants = .num n₂) ∨\n    (aexp {a₁ + a₂}).foldConstants =\n      (aexp {~a₁.foldConstants + ~a₂.foldConstants}) ∧\n    (aexp {a₁ - a₂}).foldConstants =\n      (aexp {~a₁.foldConstants - ~a₂.foldConstants}) ∧\n    (aexp {a₁ * a₂}).foldConstants =\n      (aexp {~a₁.foldConstants * ~a₂.foldConstants}) := by\n  cases ha₁ : a₁.foldConstants with\n  | num n₁ =>\n    cases ha₂ : a₂.foldConstants with\n    | num n₂ =>\n      left\n      exists n₁, n₂\n    | _ =>\n      simp [foldConstants, ha₁, ha₂]\n  | _ =>\n    simp [foldConstants, ha₁]\n\n\nThe Aexp.foldConstants_cases theorem is also a characterizing lemma, but it's\ndifferent from ones we've seen before, which have always been equations. To keep that style,\nwe might have written more lemmas like the following:-- (don't want to actually add to simp set) @[simp]\ntheorem Aexp.foldConstants_add_num\n  (h₁ : a₁.foldConstants = .num n₁)\n  (h₂ : a₂.foldConstants = .num n₂) :\n  (aexp{a₁ + a₂}).foldConstants = .num (n₁ + n₂) := by sorry\n-- @[simp]\ntheorem Aexp.foldConstants_add_other\n  (h : ¬∃ n₁ n₂,\n    a₁.foldConstants = .num n₁ ∧ a₂.foldConstants = .num n₂) :\n  (aexp{ a₁ + a₂ }).foldConstants =\n    aexp { ~a₁.foldConstants + ~a₂.foldConstants} := by sorry\n-- etc.\nThese are conditional simp lemmas — the equation in the conclusion depends on\none or more hypotheses. These hypotheses are themselves about Aexp.foldConstants,\nwhich simp would have to recursively simplify. But the hypotheses say things\nlike \"a₁.foldConstants equal to a numeral\" for an abstract a₁, and simp\ncannot further simplify that. It's a specific case a proof must consider.The Aexp.foldConstants_cases theorem helps with that, capturing a common pattern\nof compound expressions: for any a₁ and a₂, either folding turns both of them into numerals —\nin which case folding a₁ + a₂ (and -, and *) collapses to a single numeral — or at least\none of them doesn't, in which case folding a₁ + a₂ (etc.) just rebuilds the operator around\nthe already-folded operands. This theorem is meant to be consumed with cases\nto split a proof into those two scenarios; we will see its use when proving\nAexp.foldConstants_sound below.\n\nexample : (aexp { (1 + 2) * X }).foldConstants =\n        (aexp { 3 * X }) := by rfl\n\n\nNote that this version of constant folding doesn't do other\n\"obvious\" things like eliminating trivial additions (e.g.,\nrewriting 0 + X to just X): we are focusing on a single\noptimization for the sake of simplicity.It is not hard to incorporate other ways of simplifying\nexpressions - the definitions and proofs just get longer.  We'll\nconsider some in the exercises.\n\nexample : (aexp { X - ((0 * 6) + Y) }).foldConstants =\n      (aexp { X - (0 + Y) }) := by rfl\n\n\nNot only can we lift Aexp.foldConstants to Bexp in the Bexp.eq,\nBexp.neq, Bexp.le, and Bexp.gt cases, we can also look for constant\nboolean expressions and evaluate them in place as well.\n\ndef Bexp.foldConstants (b : Bexp) : Bexp :=\n  match b with\n  | bexp { true } => bexp { true }\n  | bexp { false } => bexp { false }\n  | bexp { a₁ = a₂ } =>\n    match a₁.foldConstants, a₂.foldConstants with\n    | .num n₁, .num n₂ =>\n      if n₁ = n₂ then bexp { true } else bexp { false }\n    | a₁', a₂' => bexp { a₁' = a₂' }\n  | bexp { a₁ ≠ a₂ } =>\n    match a₁.foldConstants, a₂.foldConstants with\n    | .num n₁, .num n₂ =>\n      if n₁ ≠ n₂ then bexp { true } else bexp { false }\n    | a₁', a₂' => bexp { a₁' ≠ a₂' }\n  | bexp { a₁ ≤ a₂ } =>\n    match a₁.foldConstants, a₂.foldConstants with\n    | .num n₁, .num n₂ =>\n      if n₁ ≤ n₂ then bexp { true } else bexp { false }\n    | a₁', a₂' => bexp { a₁' ≤ a₂' }\n  | bexp { a₁ > a₂ } =>\n    match a₁.foldConstants, a₂.foldConstants with\n    | .num n₁, .num n₂ =>\n      if n₁ > n₂ then bexp { true } else bexp { false }\n    | a₁', a₂' => bexp { a₁' > a₂' }\n  | bexp { ¬ b₁ } =>\n    match b₁.foldConstants with\n    | bexp { true } => bexp { false }\n    | bexp { false } => bexp { true }\n    | b₁' => bexp { ¬ b₁' }\n  | bexp { b₁ ∧ b₂ } =>\n    match b₁.foldConstants, b₂.foldConstants with\n    | bexp { true }, bexp { true } => bexp { true }\n    | bexp { true }, bexp { false } => bexp { false }\n    | bexp { false }, bexp { true } => bexp { false }\n    | bexp { false }, bexp { false } => bexp { false }\n    | b₁', b₂' => bexp { b₁' ∧ b₂' }\n\n@[simp]\ntheorem Bexp.foldConstants_true :\n    (bexp { true }).foldConstants = (bexp { true }) := by rfl\n@[simp]\ntheorem Bexp.foldConstants_false :\n    (bexp { false }).foldConstants = (bexp { false }) := by rfl\n\ntheorem Bexp.foldConstants_comp (a₁ a₂ : Aexp) :\n    (∃ n₁ n₂, a₁.foldConstants = .num n₁ ∧\n      a₂.foldConstants = .num n₂) ∨\n    (bexp {a₁ = a₂}).foldConstants =\n      (bexp {~a₁.foldConstants = ~a₂.foldConstants}) ∧\n    (bexp {a₁ ≠ a₂}).foldConstants =\n      (bexp {~a₁.foldConstants ≠ ~a₂.foldConstants}) ∧\n    (bexp {a₁ ≤ a₂}).foldConstants =\n      (bexp {~a₁.foldConstants ≤ ~a₂.foldConstants}) ∧\n    (bexp {a₁ > a₂}).foldConstants =\n      (bexp {~a₁.foldConstants > ~a₂.foldConstants}) := by\n  cases ha₁ : a₁.foldConstants with\n  | num n₁ =>\n    cases ha₂ : a₂.foldConstants with\n    | num n₂ =>\n      left\n      exists n₁, n₂\n    | _ =>\n      simp [foldConstants, ha₁, ha₂]\n  | _ => simp [foldConstants, ha₁]\n\ntheorem Bexp.foldConstants_unary (b : Bexp) :\n    (b.foldConstants = (bexp { true }) ∨\n      b.foldConstants = (bexp { false })) ∨\n    (bexp { ¬b }).foldConstants =\n      (bexp { ¬~(b.foldConstants)}) := by\n  cases hb : b.foldConstants with\n  | bool b' =>\n    simp_all\n  | _ =>\n    simp [foldConstants, hb]\n\ntheorem Bexp.foldConstants_binary (b₁ : Bexp) (b₂ : Bexp) :\n    ((b₁.foldConstants = (bexp { true }) ∨\n        b₁.foldConstants = (bexp { false })) ∧\n      (b₂.foldConstants = (bexp { true }) ∨\n        b₂.foldConstants = (bexp { false }))) ∨\n    (bexp {b₁ ∧ b₂}).foldConstants =\n      (bexp {~b₁.foldConstants ∧ ~b₂.foldConstants}) := by\n  cases hb₁ : b₁.foldConstants with\n  | bool b₁' =>\n    cases hb₂ : b₂.foldConstants with\n    | bool b₂' => simp_all\n    | _ => simp [foldConstants, hb₁, hb₂]\n  | _ => simp [foldConstants, hb₁]\n\n\nexample : (bexp { true ∧ ¬( false ∧ true) }).foldConstants =\n      (bexp { true }) := by\n  rfl\nexample : (bexp { (X = Y) ∧ ( 0 = (2 - (1 + 1))) }).foldConstants =\n      (bexp { (X = Y) ∧ true }) := by\n  rfl\n\n\nTo fold constants in a command, we simply apply the\nappropriate folding functions on all embedded expressions.\n\ndef Com.foldConstants (c : Com) : Com :=\n  match c with\n  | imp { skip } => imp { skip }\n  | imp { x := a } => imp { x := ~a.foldConstants }\n  | imp { c₁ ; c₂ } => imp { ~c₁.foldConstants ; ~c₂.foldConstants }\n  | imp { if (b) { c₁ } else { c₂ }} =>\n    match b.foldConstants with\n    | bexp { true } => c₁.foldConstants\n    | bexp { false } => c₂.foldConstants\n    | b' =>\n      imp { if (b') {~c₁.foldConstants} else { ~c₂.foldConstants} }\n  | imp { while (b) {c}} =>\n    match b.foldConstants with\n    | bexp { true } => imp { while (true) { skip }}\n    | bexp { false } => imp { skip }\n    | b' => imp { while (b') {~c.foldConstants}}\n\nexample :\n  (imp {\n    X := 4 + 5;\n    Y := X - 3;\n    if ((X - Y) = (2 + 4)) {skip} else {Y := 0};\n    if (0 ≤ (4 - (2 - 1))) {Y := 0} else {skip};\n    while (Y = 0) {X := X+1}\n  }).foldConstants =\n  (imp {\n    X := 9;\n    Y := X - 3;\n    if ((X - Y) = 6) {skip} else {Y := 0};\n    Y := 0;\n    while (Y = 0) {X := X+1}\n  }) := by rfl\n\n\n","context":"Hoare Logic\u0009Equiv: Program Equivalence\u0009Program Transformation","header":"4.3.1. The Constant-Folding Transformation","id":"/Equiv/#Hoare-Logic--Equiv___-Program-Equivalence--Program-Transformation--The-Constant-Folding-Transformation"}});